import React, { useEffect, useMemo, useState } from "react";
import {
  Mail,
  Lock,
  Eye,
  EyeOff,
  ArrowRight,
  ShieldCheck,
} from "lucide-react";

export default function Login({ onLogin, onRegister, onForgotPassword }) {
  const typewriterText = "Building better workplace through technology. Our HR and payroll management system helps organization efficiently manage their people, processes and payments."
  const isHRPortal = useMemo(() => {
    if (typeof window === "undefined") return true;
    return window.location.pathname.startsWith("/hr-manager");
  }, []);

  const role = isHRPortal ? "admin" : "employee";
  const roleLabel = isHRPortal ? "HR Admin Login" : "Employee Login";

  const [showPassword, setShowPassword] = useState(false);
  const [rememberMe, setRememberMe] = useState(true);
  const [isLoading, setIsLoading] = useState(false);
  const [form, setForm] = useState(() => ({
    email: "",
    password: "",
  }));
  const [error, setError] = useState("");
  const [showForgot, setShowForgot] = useState(false);
  const [forgotEmail, setForgotEmail] = useState("");
  const [forgotLoading, setForgotLoading] = useState(false);
  const [forgotMessage, setForgotMessage] = useState("");
  const [forgotSent, setForgotSent] = useState(false);
  // True when the server reported a failure, so a broken mail server is shown
  // as an error rather than styled like a delivered link.
  const [forgotError, setForgotError] = useState(false);
  const [typedText, setTypedText] = useState("");

  useEffect(() => {
    setTypedText("");
    let characterIndex = 0;
    const timer = window.setInterval(() => {
      characterIndex += 1;
      setTypedText(typewriterText.slice(0, characterIndex));
      if (characterIndex >= typewriterText.length) {
        window.clearInterval(timer);
      }
    }, 32);

    return () => window.clearInterval(timer);
  }, [typewriterText]);

  const handleChange = (event) => {
    setForm((current) => ({
      ...current,
      [event.target.name]: event.target.value,
    }));

    if (error) setError("");
  };

  const handleSubmit = async (event) => {
    event.preventDefault()
    setError("")

    if (!form.email.trim() || !form.password) {
      setError("Please enter your email and password.")
      return
    }

    setIsLoading(true)

    try {
      // Authenticate directly against the project's API. This intentionally
      // does not delegate role validation to a parent handler, because the
      // database uses both EMPLOYER and EMPLOYEE for the employer portal.
      const response = await fetch("/api/auth/login", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          email: form.email.trim(),
          password: form.password,
        }),
      })

      const data = await response.json().catch(() => ({}))

      if (!response.ok) {
        throw new Error(data?.message || "Invalid email or password.")
      }

      const returnedRole = String(data?.role || "").toUpperCase()
      const isEmployerAccount =
        returnedRole === "EMPLOYER" || returnedRole === "EMPLOYEE"
      const isHrAccount =
        returnedRole === "HR_MANAGER" || returnedRole === "ADMIN" || returnedRole === "HR_ADMIN"

      if (isHRPortal && !isHrAccount) {
        throw new Error(
          "This account is not an HR Admin account. Please use the Employer login page."
        )
      }

      if (!isHRPortal && !isEmployerAccount) {
        throw new Error(
          "This account is not an Employer account. Please use the HR Admin login page."
        )
      }

      const normalizedUser = {
        ...data,
        // Keep the database role when it is EMPLOYER; the routing layer can
        // normalize EMPLOYER/EMPLOYEE as needed.
        role: returnedRole === "EMPLOYEE" ? "EMPLOYEE" : returnedRole,
        company: data.company || "YanolTech",
      }

      localStorage.setItem("user", JSON.stringify(normalizedUser))
      if (rememberMe) {
        localStorage.setItem("rememberMe", "true")
      } else {
        localStorage.removeItem("rememberMe")
      }

      if (!isHRPortal && normalizedUser.mustChangePassword) {
        window.location.href = "/employer/dashboard"
        return
      }

      window.location.href = isHRPortal
        ? "/hr-manager"
        : "/employer/dashboard"
    } catch (err) {
      console.error("Login error:", err)
      setError(err?.message || "Unable to sign in. Please check your credentials.")
    } finally {
      setIsLoading(false)
    }
  }

  // Requests a single-use reset link. The new password is deliberately NOT
  // collected here: it used to be, which let anyone who knew an email address
  // overwrite that account's password without ever proving they owned it. The
  // password is now only ever set from the emailed link, which carries a
  // single-use, time-limited token.
  const handleForgotPassword = async (event) => {
    event.preventDefault();
    setForgotMessage("");
    setError("");
    setForgotError(false);

    const email = forgotEmail.trim();

    if (!email) {
      setForgotMessage("Enter your email address.");
      setForgotError(true);
      return;
    }

    setForgotLoading(true);

    try {
      const response = await fetch("/api/auth/forgot-password", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email }),
      });

      const data = await response.json().catch(() => ({}));

      if (!response.ok) {
        // The server is explicit when it could not send: either its email
        // settings are incomplete, or delivery itself failed. Neither is
        // dressed up as a successful send.
        throw new Error(data?.message || "Unable to send the reset email.");
      }

      setForgotSent(true);
      setForgotMessage(data?.message || "If that email is registered, a reset link is on its way.");
      setForm((current) => ({ ...current, email, password: "" }));
    } catch (err) {
      setForgotSent(false);
      setForgotError(true);
      setForgotMessage(err?.message || "Unable to send the reset email.");
    } finally {
      setForgotLoading(false);
    }
  };

  return (
    <>
      <style>{`
        * { box-sizing: border-box; }

        html, body, #root {
          width: 100%;
          min-height: 100%;
          margin: 0;
        }

        .ref-login-page {
          width: 100vw;
          height: 100vh;
          min-height: 760px;
          overflow: hidden;
          position: relative;
          font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
          background: linear-gradient(108deg, #148ba0 0%, #278fa2 24%, #4da5ac 52%, #7eaead 77%, #aeb1a8 100%);
        }

        .ref-login-page::before {
          content: "";
          position: absolute;
          inset: 0;
          background:
            radial-gradient(circle at 5% 25%, rgba(255,255,255,.06), transparent 26%),
            radial-gradient(circle at 73% 38%, rgba(255,255,255,.07), transparent 29%),
            radial-gradient(circle at 92% 90%, rgba(246,198,178,.14), transparent 25%);
          pointer-events: none;
        }

        /* -------------------------------------------------------
           TOP LEFT BRAND
        ------------------------------------------------------- */
        .ref-top-brand {
          position: absolute;
          z-index: 20;
          left: 54px;
          top: 43px;
          display: flex;
          align-items: center;
          gap: 4px;
          color: #fff;
        }

        .ref-top-brand-mark {
          width: 34px;
          height: 34px;
          position: relative;
          display: inline-block;
        }

        .ref-top-brand-mark::before,
        .ref-top-brand-mark::after {
          content: "";
          position: absolute;
          width: 11px;
          height: 31px;
          background: #fff;
          border-radius: 3px;
          transform: rotate(-31deg);
          top: 1px;
        }

        .ref-top-brand-mark::before { left: 6px; }
        .ref-top-brand-mark::after { right: 6px; transform: rotate(31deg); }

        .ref-top-brand-name {
          font-size: 27px;
          line-height: 1;
          font-weight: 700;
          letter-spacing: -1.3px;
        }

        /* -------------------------------------------------------
           LOGIN CARD
        ------------------------------------------------------- */
        .ref-login-card {
          position: absolute;
          z-index: 15;
          left: calc(57.4% - 662px);
          top: 96px;
          width: 520px;
          min-height: 650px;
          height: auto;
          padding: 25px 32px 22px;
          border-radius: 21px;
          background: rgba(255,255,255,.985);
          box-shadow: 0 24px 55px rgba(35,75,80,.13);
          border: 1px solid rgba(255,255,255,.95);
        }

        .ref-card-brand {
          height: 47px;
          display: flex;
          align-items: center;
          justify-content: center;
          margin-bottom: 22px;
        }

        .ref-card-mark {
          width: 35px;
          height: 35px;
          position: relative;
          display: inline-block;
          margin-right: 4px;
        }

        .ref-card-mark::before,
        .ref-card-mark::after {
          content: "";
          position: absolute;
          width: 10px;
          height: 32px;
          background: #11a8c3;
          border-radius: 3px;
          top: 1px;
          transform: rotate(-31deg);
        }

        .ref-card-mark::before { left: 6px; }
        .ref-card-mark::after { right: 6px; transform: rotate(31deg); }

        .ref-card-brand-name {
          color: #1594ad;
          font-size: 25px;
          font-weight: 800;
          letter-spacing: -1.1px;
        }

        .ref-card-heading h1 {
          margin: 0;
          color: #233b52;
          font-size: 30px;
          line-height: 1.05;
          font-weight: 800;
          letter-spacing: -1px;
          animation: refWelcomeElastic 1.45s cubic-bezier(.68,-0.6,.32,1.6) both;
          transform-origin: center center;
        }

        .ref-card-heading {
          text-align: center;
        }

        .ref-card-heading p {
          margin: 10px 0 0;
          color: #71879a;
          font-size: 14px;
          line-height: 1.45;
          white-space: nowrap;
        }

        .ref-role-badge {
          display: inline-flex;
          align-items: center;
          gap: 7px;
          margin-top: 17px;
          padding: 7px 13px;
          border-radius: 999px;
          color: #078dab;
          background: #e6f6fa;
          font-size: 13px;
          font-weight: 600;
          margin-left: auto;
          margin-right: auto;
        }

        .ref-login-error {
          margin-top: 11px;
          padding: 9px 11px;
          border-radius: 9px;
          background: #fff1f1;
          border: 1px solid #ffd8d8;
          color: #c64747;
          font-size: 12px;
        }

        .ref-login-form { margin-top: 20px; }

        .ref-field { margin-bottom: 16px; }

        .ref-input-wrap { position: relative; }

        .ref-input-icon {
          position: absolute;
          left: 18px;
          top: 50%;
          transform: translateY(-50%);
          color: #71879a;
          pointer-events: none;
        }

        .ref-input {
          width: 100%;
          height: 56px;
          border: 1px solid #d6e0e7;
          border-radius: 12px;
          background: #fff;
          color: #243b50;
          outline: none;
          padding: 0 15px 0 54px;
          font-size: 15px;
          transition: border-color .2s ease, box-shadow .2s ease;
        }

        .ref-input.password { padding-right: 51px; }

        .ref-input::placeholder { color: #91a2b0; }

        .ref-input:focus {
          border-color: #13a0b9;
          box-shadow: 0 0 0 3px rgba(19,160,185,.10);
        }

        .ref-eye {
          position: absolute;
          right: 15px;
          top: 50%;
          transform: translateY(-50%);
          border: 0;
          background: transparent;
          color: #71879a;
          padding: 5px;
          cursor: pointer;
        }

        .ref-options {
          display: flex;
          align-items: center;
          justify-content: space-between;
          margin: 1px 0 19px;
        }

        .ref-remember {
          display: flex;
          align-items: center;
          gap: 9px;
          color: #71869a;
          font-size: 13px;
          cursor: pointer;
        }

        .ref-remember input {
          width: 18px;
          height: 18px;
          margin: 0;
          accent-color: #0995b0;
        }

        .ref-forgot,
        .ref-register {
          border: 0;
          background: transparent;
          color: #008dac;
          font-size: 13px;
          font-weight: 700;
          cursor: pointer;
          padding: 0;
        }

        .ref-submit {
          width: 100%;
          height: 56px;
          border: 0;
          border-radius: 11px;
          background: #0d91aa;
          color: #fff;
          display: flex;
          align-items: center;
          justify-content: center;
          gap: 13px;
          font-size: 15px;
          font-weight: 700;
          cursor: pointer;
          box-shadow: 0 13px 26px rgba(11,145,170,.19);
          transition: transform .18s ease, background .18s ease;
        }

        .ref-submit:hover:not(:disabled) {
          background: #0a849c;
          transform: translateY(-1px);
        }

        .ref-submit:disabled { opacity: .65; cursor: not-allowed; }

        .ref-submit {
          max-width: 100%;
          min-width: 0;
          padding: 0 18px;
          white-space: nowrap;
        }

        .ref-submit svg {
          flex: 0 0 auto;
        }

        .ref-bottom {
          margin-top: 25px;
          text-align: center;
          color: #8294a3;
          font-size: 12px;
        }

        .ref-bottom .ref-register {
          color: #000;
        }

        /* -------------------------------------------------------
           RIGHT BRAND / TEXT
        ------------------------------------------------------- */
        .ref-right-copy {
          position: absolute;
          z-index: 8;
          left: calc(57.4% - 50px);
          top: calc(8.5% + 60px);
          color: #fff;
          width: 530px;
        }

        .ref-right-title {
          margin: 0;
          font-size: clamp(47px, 4.2vw, 66px);
          line-height: .98;
          font-weight: 800;
          letter-spacing: -2.2px;
        }

        .ref-right-tagline {
          margin-top: 25px;
          font-size: 12px;
          line-height: 1;
          letter-spacing: 6px;
          font-weight: 500;
          opacity: .9;
        }

        .ref-right-description {
          margin-top: 25px;
          animation: refDescriptionStretch 2.8s cubic-bezier(.22,1,.36,1) infinite;
          transform-origin: left center;
          max-width: 540px;
          color: rgba(255,255,255,.75);
          font-size: 17px;
          line-height: 1.65;
          will-change: transform, letter-spacing, opacity;
        }

        /* -------------------------------------------------------
           RIGHT-SIDE REFERENCE ILLUSTRATION
        ------------------------------------------------------- */
        .ref-illustration {
          position: absolute;
          z-index: 6;
          right: 2.6%;
          bottom: 10.6%;
          width: 500px;
          height: 420px;
          object-fit: contain;
          object-position: center bottom;
          display: block;
          background: transparent;
          pointer-events: none;
          user-select: none;
        }

        @media (max-width: 1320px) {
          .ref-login-card { left: calc(58% - 612px); }
          .ref-right-copy { left: 58%; width: 380px; }
          .ref-right-title { font-size: 49px; }
          .ref-illustration { right: 0; width: 470px; height: 395px; }
        }

        @media (max-width: 1100px) {
          .ref-login-page {
            min-height: 100vh;
            height: auto;
            overflow-y: auto;
            padding: 80px 20px 40px;
          }

          .ref-top-brand { left: 25px; top: 25px; }
          .ref-login-card {
            position: relative;
            left: auto;
            top: auto;
            width: min(520px, 100%);
            height: auto;
            margin: 0 auto;
          }
          .ref-right-copy, .ref-illustration { display: none; }
        }

        @media (max-width: 560px) {
          .ref-submit {
            width: 100%;
            height: 54px;
            padding-inline: 14px;
          }
          .ref-login-card { padding: 28px 22px 25px; border-radius: 18px; }
          .ref-card-heading p { white-space: normal; }
          .ref-card-heading h1 { font-size: 27px; }
          .ref-top-brand-name { font-size: 23px; }
        }
      `}</style>

      <main className="ref-login-page">
        {/* Top-left logo */}
        <div className="ref-top-brand">
          <img src="/logo.png" alt="Yanol-HR" className="h-10 w-10 rounded-xl object-contain" />
          <span className="ref-top-brand-name">YanolTech</span>
        </div>

        {/* Exact reference-style login card */}
        <section className="ref-login-card">
          <div className="ref-card-brand">
            <img src="/logo.png" alt="Yanol-HR" className="h-10 w-10 rounded-xl object-contain" />
            <span className="ref-card-brand-name">YanolTech</span>
          </div>

          <div className="ref-card-heading">
            <h1>Welcome Back</h1>
            <p>Sign in to your HR and Payroll management system</p>
          </div>

          <div className="ref-role-badge">
            <ShieldCheck size={15} />
            <span>{roleLabel}</span>
          </div>

          {error && <div className="ref-login-error">{error}</div>}

          <form className="ref-login-form" onSubmit={handleSubmit}>
            <div className="ref-field">
              <div className="ref-input-wrap">
                <Mail className="ref-input-icon" size={19} />
                <input
                  className="ref-input"
                  type="email"
                  name="email"
                  value={form.email}
                  onChange={handleChange}
                  placeholder="Email address"
                  autoComplete="email"
                />
              </div>
            </div>

            <div className="ref-field">
              <div className="ref-input-wrap">
                <Lock className="ref-input-icon" size={19} />
                <input
                  className="ref-input password"
                  type={showPassword ? "text" : "password"}
                  name="password"
                  value={form.password}
                  onChange={handleChange}
                  placeholder="Password"
                  autoComplete="current-password"
                />
                <button
                  type="button"
                  className="ref-eye"
                  onClick={() => setShowPassword((current) => !current)}
                  aria-label={showPassword ? "Hide password" : "Show password"}
                >
                  {showPassword ? <EyeOff size={19} /> : <Eye size={19} />}
                </button>
              </div>
            </div>

            <div className="ref-options">
              <label className="ref-remember">
                <input
                  type="checkbox"
                  checked={rememberMe}
                  onChange={(event) => setRememberMe(event.target.checked)}
                />
                <span>Remember me</span>
              </label>
            </div>

            <button
              type="submit"
              className="ref-submit"
              disabled={isLoading}
            >
              {isLoading ? (
                <>
                  <span
                    style={{
                      width: 18,
                      height: 18,
                      border: "2px solid rgba(255,255,255,.45)",
                      borderTopColor: "#fff",
                      borderRadius: "50%",
                      animation: "refSpin .8s linear infinite",
                    }}
                  />
                  Signing in...
                </>
              ) : (
                <>
                  Sign In
                  <ArrowRight size={19} />
                </>
              )}
            </button>
          </form>

          <div className="ref-bottom">
            Don't have an account?{" "}
            <button
              type="button"
              className="ref-register"
              onClick={onRegister}
            >
              Contact your HR team
            </button>
          </div>

          {showForgot && (
            <div className="ref-reset-overlay" role="dialog" aria-modal="true" aria-label="Reset password">
              <div className="ref-reset-card">
                <button
                  type="button"
                  className="ref-reset-close"
                  onClick={() => setShowForgot(false)}
                  aria-label="Close password reset"
                >
                  ×
                </button>
                <h3>Reset your password</h3>
                <p>
                  Enter your account email and we will send you a secure link to
                  choose a new password.
                </p>

                <form onSubmit={handleForgotPassword} className="ref-reset-form">
                  <input
                    className="ref-reset-input"
                    type="email"
                    required
                    value={forgotEmail}
                    onChange={(event) => {
                      setForgotEmail(event.target.value);
                      if (forgotSent) setForgotSent(false);
                      if (forgotError) setForgotError(false);
                    }}
                    placeholder="Email address"
                    autoComplete="email"
                  />
                  {forgotMessage && (
                    <div
                      className={`ref-reset-message${forgotError ? " ref-reset-message--error" : ""}`}
                    >
                      {forgotMessage}
                    </div>
                  )}
                  {forgotSent && (
                    <p className="ref-reset-hint">
                      The link expires in 30 minutes and can only be used once.
                      Open it on the device where you are signing in.
                    </p>
                  )}
                  <button type="submit" className="ref-reset-submit" disabled={forgotLoading}>
                    {forgotLoading ? "Sending link..." : "Send reset link"}
                  </button>
                </form>
              </div>
            </div>
          )}
        </section>

        {/* Right-side reference text */}
        <section className="ref-right-copy" aria-label="YanolTech introduction">
          <h2 className="ref-right-title">YANOL TECH</h2>
          <div className="ref-right-tagline">TOGETHER WE RISE</div>
                  <p className="ref-typewriter mt-6 max-w-[570px] text-[17px] leading-8 text-white/85">
                    {typedText}
                  </p>
        </section>

        {/* Right-side reference illustration */}
        <img
          className="ref-illustration"
          src="data:image/png;base64,"
          alt=""
          aria-hidden="true"
        />

      </main>

      <style>{`
        @keyframes refSpin {
          to { transform: rotate(360deg); }
        }

        .ref-typewriter {
          position: relative;
          min-height: 8rem;
        }

        .ref-typewriter::after {
          content: "";
          display: inline-block;
          width: 2px;
          height: 1.1em;
          margin-left: 5px;
          vertical-align: -0.15em;
          background: rgba(255, 255, 255, .9);
          animation: refCaret .8s steps(1, end) infinite;
        }

        @keyframes refCaret {
          50% { opacity: 0; }
        }

        @keyframes refWelcomeElastic {
          0% { opacity: 0; transform: translateY(-18px) rotate(-8deg) scale(.72); letter-spacing: 5px; }
          35% { opacity: 1; transform: translateY(4px) rotate(4deg) scale(1.08); letter-spacing: -1.8px; }
          58% { transform: translateY(-2px) rotate(-2deg) scale(.97); }
          78% { transform: translateY(1px) rotate(1deg) scale(1.02); }
          100% { opacity: 1; transform: translateY(0) rotate(0deg) scale(1); letter-spacing: -1px; }
        }

        @keyframes refDescriptionStretch {
          0%, 100% {
            opacity: .72;
            transform: translateY(0) scaleX(1);
            letter-spacing: 0;
          }
          45% {
            opacity: 1;
            transform: translateY(-2px) scaleX(1.045);
            letter-spacing: .35px;
          }
          65% {
            opacity: .96;
            transform: translateY(0) scaleX(1.015);
            letter-spacing: .12px;
          }
        }

        .ref-bouncy-period {
          display: inline-block;
          animation: refPeriodBounce 1.7s ease-in-out infinite;
          transform-origin: 50% 100%;
        }

        .ref-bouncy-period:nth-of-type(2) {
          animation-delay: .22s;
        }

        .ref-reset-overlay {
          position: fixed;
          inset: 0;
          z-index: 100;
          display: flex;
          align-items: center;
          justify-content: center;
          padding: 20px;
          background: rgba(24,55,64,.42);
          backdrop-filter: blur(5px);
        }

        .ref-reset-card {
          position: relative;
          width: min(390px, 100%);
          padding: 28px;
          border-radius: 20px;
          background: #fff;
          box-shadow: 0 25px 60px rgba(25,55,65,.25);
        }

        .ref-reset-card h3 { margin: 0; color: #233b52; font-size: 23px; }
        .ref-reset-card p { margin: 8px 0 20px; color: #71879a; font-size: 13px; line-height: 1.5; }
        .ref-reset-close { position: absolute; top: 10px; right: 14px; border: 0; background: transparent; color: #71879a; font-size: 27px; cursor: pointer; }
        .ref-reset-form { display: grid; gap: 12px; }
        .ref-reset-input { width: 100%; height: 48px; border: 1px solid #d6e0e7; border-radius: 10px; padding: 0 13px; outline: none; color: #243b50; }
        .ref-reset-input:focus { border-color: #13a0b9; box-shadow: 0 0 0 3px rgba(19,160,185,.10); }
        .ref-reset-message { padding: 10px 12px; border-radius: 9px; background: #eef9f5; color: #18785b; font-size: 12px; line-height: 1.45; }
        /* A configuration or delivery failure is shown in a different colour
           from a success, so a broken mail server is never mistaken for an
           email that is on its way. */
        .ref-reset-message.ref-reset-message--error { background: #fdeeee; color: #a12c2c; }
        .ref-reset-hint { margin: 0; color: #64798c; font-size: 11px; line-height: 1.5; }
        .ref-reset-submit { height: 50px; border: 0; border-radius: 10px; background: #0d91aa; color: #fff; font-weight: 700; cursor: pointer; }
        .ref-reset-submit:disabled { opacity: .65; cursor: not-allowed; }

        @keyframes refPeriodBounce {
          0%, 100% { transform: translateY(0) scale(1); }
          18% { transform: translateY(-5px) scale(1.18); }
          32% { transform: translateY(1px) scale(.92); }
          45% { transform: translateY(-3px) scale(1.08); }
          58% { transform: translateY(0) scale(1); }
        }
      `}</style>
    </>
  );
}
